original_prompt:
{
  "system_instruction": "Act as a senior brand identity designer. Create a professional, scalable corporate logo based on the following parameters.",
  "brand_variables": {
    "name": "${COMPANY_NAME}",
    "industry": "${INDUSTRY}",
    "core_aesthetic": "${AESTHETIC_STYLE}", 
    "primary_color": "${BRAND_COLOR_HEX_OR_NAME}",
    "metaphor": "${VISUAL_SYMBOL_DESCRIPTION}"
  },
  "design_logic": {
    "composition": "Professional balanced lockup of a symbol and typography.",
    "typography": "High-fidelity rendering of '${COMPANY_NAME}'. Style: Bold, modern, sans-serif, optimized kerning.",
    "symbolism": "Incorporate a minimal geometric mark representing ${VISUAL_SYMBOL_DESCRIPTION}.",
    "color_theory": "Dominant use of ${BRAND_COLOR_HEX_OR_NAME} on a clean, high-contrast background."
  },
  "nano_banana_constraints": {
    "style_reference": "Swiss Graphic Design, Modern Corporate Minimalism",
    "technical_specs": [
      "Vector-style clarity",
      "No 3D effects or drop shadows",
      "Solid flat colors",
      "Maximum legibility at small scale"
    ],
    "negative_space": "Utilize intentional white space to enhance the ${AESTHETIC_STYLE} feel."
  },
  "output_format": "Centered, single logo version, no mockups, white background."
}

vi_prompt:
{
  "system_instruction": "Hãy đóng vai một chuyên gia thiết kế bộ nhận diện thương hiệu cao cấp. Thiết kế một logo doanh nghiệp chuyên nghiệp, có khả năng mở rộng kích thước dựa trên các thông số sau.",
  "brand_variables": {
    "name": "${COMPANY_NAME}",
    "industry": "${INDUSTRY}",
    "core_aesthetic": "${AESTHETIC_STYLE}", 
    "primary_color": "${BRAND_COLOR_HEX_OR_NAME}",
    "metaphor": "${VISUAL_SYMBOL_DESCRIPTION}"
  },
  "design_logic": {
    "composition": "Bố cục kết hợp cân đối chuyên nghiệp giữa biểu tượng (symbol) và kiểu chữ thương hiệu (typography).",
    "typography": "Thể hiện độ sắc nét cao của '${COMPANY_NAME}'. Phong cách: Đậm, hiện đại, không chân (sans-serif), tối ưu hóa khoảng cách ký tự (kerning).",
    "symbolism": "Kết hợp một biểu tượng hình học tối giản đại diện cho ${VISUAL_SYMBOL_DESCRIPTION}.",
    "color_theory": "Sử dụng màu chủ đạo ${BRAND_COLOR_HEX_OR_NAME} trên nền sạch sẽ, độ tương phản cao."
  },
  "nano_banana_constraints": {
    "style_reference": "Thiết kế đồ họa phong cách Thụy Sĩ (Swiss Graphic Design), Phong cách tối giản doanh nghiệp hiện đại",
    "technical_specs": [
      "Độ sắc nét chuẩn phong cách vector",
      "Không có hiệu ứng 3D hoặc bóng đổ",
      "Màu phẳng nguyên khối (solid flat colors)",
      "Độ rõ ràng và dễ nhận diện tối đa ở kích thước nhỏ"
    ],
    "negative_space": "Sử dụng khoảng trắng có chủ đích để nâng cao cảm giác ${AESTHETIC_STYLE}."
  },
  "output_format": "Căn giữa, một phiên bản logo duy nhất, không dùng mockup phối cảnh, nền trắng."
}
